let parent_transcript_path = match sess

.services

.thread_store

.read_thread(ReadThreadParams {

thread_id: *parent_thread_id,

include_archived: true,

include_history: false,

})

.await

{

Ok(thread) => thread.rollout_path,

Err(error) => {

tracing::warn!(

